/**
 * Shared UX helpers for onboarding, data quality, and sustainability storytelling.
 */

export type DataConfidenceLevel = 'high' | 'medium' | 'low';

export interface DataQualityInput {
  hasProfile: boolean;
  hasAssessment: boolean;
  carbonEmissionsKg: number;
  transactionCount?: number;
  documentCount?: number;
  hasScopeBreakdown?: boolean;
  /** From inventoryMetadata.completenessScore (0–100) when available. */
  inventoryCompletenessScore?: number;
  /** Share of transactions with activity-based quantification (0–100). */
  activitySharePct?: number;
}

export interface DataQualityResult {
  score: number;
  level: DataConfidenceLevel;
  label: string;
  hints: string[];
}

export interface OnboardingStep {
  id: string;
  label: string;
  description: string;
  path: string;
  complete: boolean;
}

export interface OnboardingProgress {
  steps: OnboardingStep[];
  completedCount: number;
  totalCount: number;
  percent: number;
  allComplete: boolean;
}

export interface NextBestAction {
  title: string;
  description: string;
  path: string;
  impactLabel?: string;
  effortLabel?: string;
  ctaLabel: string;
}

export interface EnvironmentalEquivalents {
  treesEquivalent: number;
  carsOffRoadDays: number;
  kwhEquivalent: number;
}

export const IMPLEMENTED_RECOMMENDATIONS_STORAGE_KEY = 'ci-implemented-recommendations-v1';
export const CARBON_WIZARD_DRAFT_STORAGE_KEY = 'ci-carbon-wizard-draft-v1';

const clamp = (n: number, min: number, max: number) => Math.min(max, Math.max(min, n));

export function computeDataQualityScore(input: DataQualityInput): DataQualityResult {
  let score = 0;
  const hints: string[] = [];

  if (input.hasProfile) {
    score += 25;
  } else {
    hints.push('Complete your company profile for sector-specific defaults.');
  }

  if (input.hasAssessment && input.carbonEmissionsKg > 0) {
    score += 35;
  } else {
    hints.push('Run a carbon assessment to establish your baseline footprint.');
  }

  if ((input.transactionCount ?? 0) > 0) {
    score += 20;
  } else {
    hints.push('Add or classify transactions to strengthen operational data.');
  }

  if ((input.documentCount ?? 0) > 0) {
    score += 10;
  } else {
    hints.push('Upload utility bills or invoices for document-backed evidence.');
  }

  if (input.hasScopeBreakdown) {
    score += 10;
  } else {
    hints.push('Save an assessment with scope 1–3 splits for disclosure-ready reporting.');
  }

  if (typeof input.inventoryCompletenessScore === 'number' && input.inventoryCompletenessScore > 0) {
    score = Math.round((score * 0.65) + (clamp(input.inventoryCompletenessScore, 0, 100) * 0.35));
  }

  if (typeof input.activitySharePct === 'number' && input.activitySharePct < 20) {
    hints.push('Add metered kWh, liters, or kg on bills to raise activity-based data share.');
  }

  const finalScore = clamp(score, 0, 100);
  let level: DataConfidenceLevel = 'low';
  let label = 'Low confidence — more data needed';

  if (finalScore >= 75) {
    level = 'high';
    label = 'High confidence — multi-source inventory';
  } else if (finalScore >= 45) {
    level = 'medium';
    label = 'Medium confidence — partial evidence';
  }

  return { score: finalScore, level, label, hints: hints.slice(0, 3) };
}

export function deriveOnboardingSteps(input: {
  hasProfile: boolean;
  hasDocuments: boolean;
  hasAssessment: boolean;
  hasTargets: boolean;
}): OnboardingProgress {
  const steps: OnboardingStep[] = [
    {
      id: 'profile',
      label: 'Company profile',
      description: 'Sector, scale, and registration details',
      path: '/msme-profile',
      complete: input.hasProfile,
    },
    {
      id: 'documents',
      label: 'Upload evidence',
      description: 'Bills, invoices, or connector data',
      path: '/data?tab=0',
      complete: input.hasDocuments,
    },
    {
      id: 'assessment',
      label: 'Carbon assessment',
      description: 'Wizard + operational inputs',
      path: '/carbon-footprint?section=start-assessment',
      complete: input.hasAssessment,
    },
    {
      id: 'targets',
      label: 'Set reduction target',
      description: 'Track progress against your goal',
      path: '/emissions-reduction-targets?tab=1',
      complete: input.hasTargets,
    },
  ];

  const completedCount = steps.filter((s) => s.complete).length;
  const totalCount = steps.length;

  return {
    steps,
    completedCount,
    totalCount,
    percent: totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0,
    allComplete: completedCount === totalCount,
  };
}

export function deriveNextBestAction(input: {
  hasProfile: boolean;
  hasDocuments: boolean;
  hasAssessment: boolean;
  carbonScore: number;
  topRecommendationTitle?: string;
  topRecommendationKg?: number;
}): NextBestAction {
  if (!input.hasProfile) {
    return {
      title: 'Complete your company profile',
      description: 'Unlock sector defaults, compliance checks, and tailored reduction ideas.',
      path: '/msme-profile',
      effortLabel: '~5 min',
      ctaLabel: 'Open profile',
    };
  }

  if (!input.hasDocuments) {
    return {
      title: 'Upload your first evidence document',
      description: 'Utility bills and invoices improve accuracy versus estimates alone.',
      path: '/data?tab=0',
      effortLabel: '~3 min',
      impactLabel: 'Higher data quality',
      ctaLabel: 'Upload documents',
    };
  }

  if (!input.hasAssessment) {
    return {
      title: 'Run your first carbon assessment',
      description: 'Combine operational inputs with documents to see scope mix and hotspots.',
      path: '/carbon-footprint?section=start-assessment',
      effortLabel: '~15 min',
      impactLabel: 'Baseline footprint',
      ctaLabel: 'Start assessment',
    };
  }

  if (input.carbonScore > 0 && input.carbonScore < 60) {
    return {
      title: input.topRecommendationTitle || 'Review top reduction action',
      description: 'Your score suggests corrective action — prioritize the highest-impact initiative.',
      path: '/emissions-reduction-targets?tab=2',
      impactLabel: input.topRecommendationKg
        ? `~${input.topRecommendationKg.toFixed(0)} kg CO₂e potential`
        : 'Reduction opportunities',
      effortLabel: 'Varies',
      ctaLabel: 'View recommendations',
    };
  }

  return {
    title: 'Check compliance readiness',
    description: 'See India and export disclosure gaps before your next reporting cycle.',
    path: '/compliance',
    effortLabel: '~5 min',
    ctaLabel: 'Open compliance hub',
  };
}

/** Prefer AI goal-advisor action when MSME advisory orchestration has run. */
export function deriveNextBestActionFromAdvisory(
  fallback: NextBestAction,
  advisoryAction?: {
    title?: string;
    description?: string;
    path?: string;
    priority?: string;
  } | null
): NextBestAction {
  if (!advisoryAction?.path) {
    return fallback;
  }
  return {
    title: advisoryAction.title || fallback.title,
    description: advisoryAction.description || fallback.description,
    path: advisoryAction.path,
    ctaLabel: 'Take action',
    impactLabel: advisoryAction.priority === 'high' ? 'AI priority' : fallback.impactLabel,
    effortLabel: fallback.effortLabel,
  };
}

export interface TrustPanelScores {
  dataCompletenessScore: number;
  inventoryQualityScore: number;
  inventoryQualityLevel?: string;
  uncertaintyNote?: string;
  activitySharePct?: number;
}

/** Rough equivalency factors for user-facing context (not for inventory calculations). */
export interface FrameworkDataGap {
  framework: string;
  gap: string;
  actionPath: string;
  actionLabel: string;
}

/** Map data-quality gaps to disclosure-oriented next steps (BRSR / export). */
export function deriveFrameworkDataGaps(input: DataQualityInput): FrameworkDataGap[] {
  const gaps: FrameworkDataGap[] = [];

  if (!input.hasProfile) {
    gaps.push({
      framework: 'BRSR Core',
      gap: 'Company profile incomplete for sector-specific intensity benchmarks.',
      actionPath: '/msme-profile',
      actionLabel: 'Complete profile',
    });
  }

  if (!input.hasAssessment || input.carbonEmissionsKg <= 0) {
    gaps.push({
      framework: 'BRSR Principle 6',
      gap: 'No baseline greenhouse gas inventory on file.',
      actionPath: '/carbon-footprint?section=start-assessment',
      actionLabel: 'Run assessment',
    });
  }

  if ((input.documentCount ?? 0) === 0) {
    gaps.push({
      framework: 'Assurance readiness',
      gap: 'No document-backed evidence (utility bills, invoices, or connectors).',
      actionPath: '/data?tab=0',
      actionLabel: 'Upload evidence',
    });
  }

  if (!input.hasScopeBreakdown) {
    gaps.push({
      framework: 'Export (CBAM / CSRD)',
      gap: 'Scope 1–3 split missing for product- and value-chain disclosures.',
      actionPath: '/carbon-footprint?section=assessment-results',
      actionLabel: 'Review scopes',
    });
  }

  if ((input.transactionCount ?? 0) === 0) {
    gaps.push({
      framework: 'Operational inventory',
      gap: 'No classified transactions — spend-based signals improve hotspot accuracy.',
      actionPath: '/data?tab=1',
      actionLabel: 'Add transactions',
    });
  }

  return gaps.slice(0, 4);
}

export function computeEnvironmentalEquivalents(kgCo2: number): EnvironmentalEquivalents {
  const kg = Math.max(0, Number(kgCo2) || 0);
  return {
    treesEquivalent: Math.max(0, Math.round(kg / 21)),
    carsOffRoadDays: Math.max(0, Math.round(kg / 4.6)),
    kwhEquivalent: Math.max(0, Math.round(kg / 0.82)),
  };
}

export function loadImplementedRecommendationIds(): Set<string> {
  if (typeof window === 'undefined') {
    return new Set();
  }
  try {
    const raw = window.localStorage.getItem(IMPLEMENTED_RECOMMENDATIONS_STORAGE_KEY);
    if (!raw) return new Set();
    const parsed = JSON.parse(raw);
    return new Set(Array.isArray(parsed) ? parsed.filter((id) => typeof id === 'string') : []);
  } catch {
    return new Set();
  }
}

export function saveImplementedRecommendationIds(ids: Set<string>): void {
  if (typeof window === 'undefined') {
    return;
  }
  window.localStorage.setItem(IMPLEMENTED_RECOMMENDATIONS_STORAGE_KEY, JSON.stringify(Array.from(ids)));
}

export function markRecommendationImplemented(id: string): Set<string> {
  const next = loadImplementedRecommendationIds();
  next.add(id);
  saveImplementedRecommendationIds(next);
  return next;
}

export interface CompletenessResult {
  score: number;
  label: string;
  hints: string[];
}

const hasStr = (v: unknown) => typeof v === 'string' && v.trim().length > 0;

/** MSME company profile completeness for B2B engagement cues. */
export function computeMsmeProfileCompleteness(profile: Record<string, unknown> | null | undefined): CompletenessResult {
  if (!profile) {
    return { score: 0, label: 'Profile not started', hints: ['Register your company to unlock tailored defaults.'] };
  }

  let score = 0;
  const hints: string[] = [];
  const checks: Array<{ ok: boolean; hint: string; weight: number }> = [
    { ok: hasStr(profile.companyName), hint: 'Add legal company name', weight: 15 },
    { ok: hasStr(profile.gstNumber), hint: 'Add GST number for buyer verification', weight: 15 },
    { ok: hasStr(profile.udyamRegistrationNumber), hint: 'Add Udyam registration number', weight: 10 },
    { ok: hasStr(profile.industry), hint: 'Select industry sector', weight: 10 },
    {
      ok: hasStr((profile.contact as { email?: string })?.email),
      hint: 'Add contact email',
      weight: 10,
    },
    {
      ok: hasStr((profile.contact as { phone?: string })?.phone),
      hint: 'Add contact phone',
      weight: 5,
    },
    {
      ok: hasStr((profile.manufacturingProfile as { industrySector?: string })?.industrySector),
      hint: 'Complete manufacturing sector details',
      weight: 15,
    },
    {
      ok: (() => {
        const org = (profile.manufacturingProfile as {
          ghgOrganizationalBoundary?: { reportingEntityDescription?: string; consolidationApproach?: string };
        })?.ghgOrganizationalBoundary;
        const orgDesc = typeof org?.reportingEntityDescription === 'string'
          ? org.reportingEntityDescription.trim()
          : '';
        return Boolean(org?.consolidationApproach) && orgDesc.length >= 20;
      })(),
      hint: 'Document organizational boundary under Profile (reporting entity & consolidation)',
      weight: 10,
    },
    {
      ok: (() => {
        const op = (profile.operations as {
          ghgOperationalBoundary?: {
            baseYear?: number;
            scope3CategoriesIncluded?: number[];
            scope2LocationBased?: boolean;
            scope1StationaryCombustion?: boolean;
          };
        })?.ghgOperationalBoundary;
        const scope3Included = op?.scope3CategoriesIncluded;
        const scope3 = Array.isArray(scope3Included) ? scope3Included : [];
        const hasScope1 = Boolean(
          op?.scope1StationaryCombustion
          || (op as { scope1MobileCombustion?: boolean })?.scope1MobileCombustion
        );
        const hasScope2 = Boolean(op?.scope2LocationBased || (op as { scope2MarketBased?: boolean })?.scope2MarketBased);
        return Number(op?.baseYear) >= 1990 && hasScope1 && hasScope2 && scope3.length > 0;
      })(),
      hint: 'Configure operational boundary (Scopes 1–3) under Operations',
      weight: 10,
    },
  ];

  checks.forEach(({ ok, hint, weight }) => {
    if (ok) score += weight;
    else hints.push(hint);
  });

  const finalScore = clamp(score, 0, 100);
  let label = 'Needs attention — complete core fields';
  if (finalScore >= 85) label = 'Audit-ready profile';
  else if (finalScore >= 55) label = 'Good progress — a few gaps remain';

  return { score: finalScore, label, hints: hints.slice(0, 3) };
}

/** Enterprise organization profile completeness. */
export function computeEnterpriseProfileCompleteness(
  profile: Record<string, unknown> | null | undefined
): CompletenessResult {
  if (!profile) {
    return { score: 0, label: 'Organization not registered', hints: ['Complete enterprise registration first.'] };
  }

  let score = 0;
  const hints: string[] = [];
  const facilities = Array.isArray(profile.facilities) ? profile.facilities : [];
  const validFacilities = facilities.filter(
    (f) => hasStr((f as { name?: string }).name) && hasStr((f as { state?: string }).state)
  );
  const scope3 = (profile.scope3Materiality as { categories?: unknown[] })?.categories || [];

  const checks: Array<{ ok: boolean; hint: string; weight: number }> = [
    { ok: hasStr(profile.companyName), hint: 'Add legal company name', weight: 15 },
    { ok: hasStr(profile.cinNumber), hint: 'Add CIN for listing disclosure', weight: 15 },
    { ok: hasStr(profile.industry), hint: 'Add industry sector', weight: 10 },
    { ok: hasStr(profile.consolidationApproach), hint: 'Set consolidation approach', weight: 10 },
    { ok: validFacilities.length >= 1, hint: 'Add at least one facility (Scope 1–2)', weight: 20 },
    {
      ok: scope3.length >= 5,
      hint: 'Configure Scope 3 materiality categories',
      weight: 15,
    },
    {
      ok: Boolean((profile.regulatoryMandates as { sebiBrsr?: boolean })?.sebiBrsr)
        || Boolean((profile.regulatoryMandates as { patScheme?: boolean })?.patScheme),
      hint: 'Confirm applicable regulatory mandates',
      weight: 15,
    },
  ];

  checks.forEach(({ ok, hint, weight }) => {
    if (ok) score += weight;
    else hints.push(hint);
  });

  const finalScore = clamp(score, 0, 100);
  let label = 'Disclosure setup in progress';
  if (finalScore >= 85) label = 'Strong BRSR foundation';
  else if (finalScore >= 55) label = 'Core org data captured';

  return { score: finalScore, label, hints: hints.slice(0, 3) };
}

export function deriveEnterpriseOnboardingSteps(input: {
  hasProfile: boolean;
  profileCompleteness: number;
  workflowComplete: boolean;
  hasDocuments: boolean;
  hasConnectors: boolean;
  hasAssessment: boolean;
}): OnboardingProgress {
  const steps: OnboardingStep[] = [
    {
      id: 'org_profile',
      label: 'Organization profile',
      description: 'CIN, mandates, facilities, and Scope 3 materiality',
      path: '/enterprise/profile',
      complete: input.hasProfile && input.profileCompleteness >= 55,
    },
    {
      id: 'workflow',
      label: 'Compliance workflow',
      description: 'Evidence-backed BRSR / PAT / ICM sections',
      path: '/enterprise/workflow',
      complete: input.workflowComplete,
    },
    {
      id: 'data',
      label: 'Connect data',
      description: 'Accounting connectors or facility documents',
      path: '/enterprise/data?section=connectors',
      complete: input.hasDocuments || input.hasConnectors,
    },
    {
      id: 'inventory',
      label: 'Carbon inventory',
      description: 'Scope 1–3 assessment and disclosure pack',
      path: '/enterprise/carbon-footprint',
      complete: input.hasAssessment,
    },
  ];

  const completedCount = steps.filter((s) => s.complete).length;
  const totalCount = steps.length;

  return {
    steps,
    completedCount,
    totalCount,
    percent: totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0,
    allComplete: completedCount === totalCount,
  };
}

export function deriveEnterpriseNextBestAction(input: {
  profileCompleteness: number;
  workflowComplete: boolean;
  hasDocuments: boolean;
  hasConnectors: boolean;
  hasAssessment: boolean;
  readinessScore: number;
}): NextBestAction {
  if (input.profileCompleteness < 55) {
    return {
      title: 'Strengthen organization profile',
      description: 'Add facilities and Scope 3 materiality so BRSR and PAT workflows have the right boundaries.',
      path: '/enterprise/profile',
      effortLabel: '~10 min',
      ctaLabel: 'Open organization',
    };
  }

  if (!input.workflowComplete) {
    return {
      title: 'Complete compliance workflow sections',
      description: 'Each section unlocks when profile evidence is in place — no empty checkboxes.',
      path: '/enterprise/workflow',
      effortLabel: '~20 min',
      impactLabel: 'Mandate readiness',
      ctaLabel: 'Continue workflow',
    };
  }

  if (!input.hasDocuments && !input.hasConnectors) {
    return {
      title: 'Connect accounting or upload facility bills',
      description: 'Finance-led data improves hotspot accuracy and assurance readiness.',
      path: '/enterprise/data?section=connectors',
      effortLabel: '~5 min',
      impactLabel: 'Higher data quality',
      ctaLabel: 'Add data',
    };
  }

  if (!input.hasAssessment) {
    return {
      title: 'Run enterprise carbon inventory',
      description: 'Build scope 1–3 totals aligned with your selected mandates.',
      path: '/enterprise/carbon-footprint',
      effortLabel: '~15 min',
      impactLabel: 'Baseline inventory',
      ctaLabel: 'Open inventory',
    };
  }

  if (input.readinessScore > 0 && input.readinessScore < 70) {
    return {
      title: 'Close compliance gaps',
      description: 'Review BRSR / PAT gaps before your next reporting cycle.',
      path: '/enterprise/compliance',
      impactLabel: `${input.readinessScore}% readiness`,
      ctaLabel: 'Review compliance',
    };
  }

  return {
    title: 'Generate disclosure report',
    description: 'Export BRSR-aligned outputs when your inventory and workflow are complete.',
    path: '/enterprise/reporting',
    effortLabel: '~5 min',
    ctaLabel: 'Open reporting',
  };
}

/** Combined customer health score for dashboard headers (MSME or enterprise). */
export function computeCustomerHealthScore(parts: {
  profileScore: number;
  dataOrWorkflowScore: number;
  assessmentOrReadinessScore: number;
}): { score: number; label: string } {
  const score = Math.round(
    parts.profileScore * 0.35
      + parts.dataOrWorkflowScore * 0.35
      + parts.assessmentOrReadinessScore * 0.3
  );
  const finalScore = clamp(score, 0, 100);
  let label = 'Getting started';
  if (finalScore >= 75) label = 'Strong — disclosure-ready trajectory';
  else if (finalScore >= 45) label = 'On track — finish key setup steps';

  return { score: finalScore, label };
}
