import { PLAN_LIMITS, resolvePlanTierKey, type PlanTier } from '../constants/pricingPlans';

export type GatedFeature = 'complianceHub' | 'brsrExports' | 'greenFinance' | 'carbonCredits';

const FEATURE_LABELS: Record<GatedFeature, string> = {
  complianceHub: 'Compliance hub',
  brsrExports: 'BRSR-oriented exports',
  greenFinance: 'Green finance matching',
  carbonCredits: 'Carbon credits workspace',
};

/** Resolve effective tier from billing profile or default to free. */
export function resolveEffectivePlanTier(selectedPlanId?: string | null, status?: string): PlanTier {
  if (!selectedPlanId || status !== 'paid') {
    return 'free';
  }
  return resolvePlanTierKey(selectedPlanId);
}

export function planHasFeature(tier: PlanTier, feature: GatedFeature): boolean {
  return Boolean(PLAN_LIMITS[tier][feature]);
}

export function getUpgradeMessage(feature: GatedFeature, currentTier: PlanTier): string {
  const label = FEATURE_LABELS[feature];
  if (planHasFeature(currentTier, feature)) {
    return '';
  }
  return `${label} is available on the Growth plan and above. You are on ${currentTier === 'free' ? 'Free' : currentTier}.`;
}

export function getDocumentLimitWarning(
  tier: PlanTier,
  documentCount: number
): { atLimit: boolean; message: string } | null {
  const limit = PLAN_LIMITS[tier].documentsPerMonth;
  if (documentCount < limit * 0.85) {
    return null;
  }
  const atLimit = documentCount >= limit;
  return {
    atLimit,
    message: atLimit
      ? `You have reached your ${limit} documents/month limit on the ${tier} plan. Upgrade to Growth for 200 docs/mo or pay ₹12 per extra document.`
      : `You have used ${documentCount} of ${limit} documents this month. Consider upgrading before you hit the limit.`,
  };
}

export const GROWTH_PLAN_ID = 'msme_growth_monthly';
